import{_ as l,a0 as o,w as p,s as d,I as e,x as i,a1 as n,A as t,ao as h}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"迁徙到 Linux：命令行环境 | LCTT x X-CMD","titleTemplate":false,"description":"迁徙到 Linux：命令行环境 | LCTT (201804) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"迁徙到 Linux：命令行环境 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"迁徙到 Linux：命令行环境 | LCTT (201804) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201804/20180123 Migrating to Linux- The Command Line","title":"迁徙到 Linux：命令行环境","tag":"201804","desc":""},"relativePath":"201804/20180123 Migrating to Linux- The Command Line.md","filePath":"[post].md"}'),c={name:"201804/20180123 Migrating to Linux- The Command Line.md"};function r(g,s,u,k,b,f){const a=o("Link");return p(),d("div",null,[s[20]||(s[20]=e("h1",{id:"迁徙到-linux-命令行环境",tabindex:"-1"},[i("迁徙到 Linux：命令行环境 "),e("a",{class:"header-anchor",href:"#迁徙到-linux-命令行环境","aria-label":"Permalink to “迁徙到 Linux：命令行环境”"},"​")],-1)),s[21]||(s[21]=e("blockquote",null,[e("p",null,"刚接触 Linux？在这篇教程中将学习如何轻松地在命令行列出、移动和编辑文件。")],-1)),s[22]||(s[22]=e("p",null,[e("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/migrate.jpg?itok=2PBkvV7s",alt:""})],-1)),e("p",null,[s[3]||(s[3]=i("这是关于迁徙到 Linux 系列的第四篇文章了。如果您错过了之前的内容，可以回顾我们之前谈到的内容 ",-1)),n(a,{href:"https://linux.cn/article-9212-1.html"},{default:t(()=>[...s[0]||(s[0]=[i("新手之 Linux",-1)])]),_:1}),s[4]||(s[4]=i("、",-1)),n(a,{href:"https://linux.cn/article-9213-1.html"},{default:t(()=>[...s[1]||(s[1]=[i("文件和文件系统",-1)])]),_:1}),s[5]||(s[5]=i("、和 ",-1)),n(a,{href:"https://linux.cn/article-9293-1.html"},{default:t(()=>[...s[2]||(s[2]=[i("图形环境",-1)])]),_:1}),s[6]||(s[6]=i("。Linux 无处不在，它可以用于运行大部分的网络服务器，如 Web、email 和其他服务器；它同样可以在您的手机、汽车控制台和其他很多设备上使用。现在，您可能会开始好奇 Linux 系统，并对学习 Linux 的工作原理萌发兴趣。",-1))]),s[23]||(s[23]=h(`<p>在 Linux 下，命令行非常实用。Linux 的桌面系统中，尽管命令行只是可选操作，但是您依旧能看见很多朋友开着一个命令行窗口和其他应用窗口并肩作战。在互联网服务器上和在设备中运行 Linux 时（LCTT 译注：指 IoT），命令行通常是唯一能直接与操作系统交互的工具。因此，命令行是有必要了解的，至少应当涉猎一些基础命令。</p><p>在命令行（通常称之为 Linux shell）中，所有操作都是通过键入命令完成。您可以执行查看文件列表、移动文件位置、显示文件内容、编辑文件内容等一系列操作，通过命令行，您甚至可以查看网页中的内容。</p><p>如果您在 Windows（CMD 或者 PowerShell） 上已经熟悉关于命令行的使用，您是否想跳转到“Windows 命令行用户”的章节上去？先阅读这些内容吧。</p><h3 id="导航" tabindex="-1">导航 <a class="header-anchor" href="#导航" aria-label="Permalink to “导航”">​</a></h3><p>在命令行中，这里有一个当前工作目录（文件夹和目录是同义词，在 Linux 中它们通常都被称为目录）的概念。如果没有特别指定目录，许多命令的执行会在当前目录下生效。比如，键入 <code>ls</code> 列出文件目录，当前工作目录的文件将会被列举出来。看一个例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls</span></span>
<span class="line"><span>Desktop Documents Downloads Music Pictures README.txt Videos</span></span></code></pre></div><p><code>ls Documents</code> 这条命令将会列出 <code>Documents</code> 目录下的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls Documents</span></span>
<span class="line"><span>report.txt todo.txt EmailHowTo.pdf</span></span></code></pre></div><p>通过 <code>pwd</code> 命令可以显示当前您的工作目录。比如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pwd</span></span>
<span class="line"><span>/home/student</span></span></code></pre></div><p>您可以通过 <code>cd</code> 命令改变当前目录并切换到您想要抵达的目录。比如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pwd</span></span>
<span class="line"><span>/home/student</span></span>
<span class="line"><span>$ cd Downloads</span></span>
<span class="line"><span>$ pwd</span></span>
<span class="line"><span>/home/student/Downloads</span></span></code></pre></div><p>路径中的目录由 <code>/</code>（左斜杠）字符分隔。路径中有一个隐含的层次关系，比如 <code>/home/student</code> 目录中，home 是顶层目录，而 <code>student</code> 是 <code>home</code> 的子目录。</p><p>路径要么是绝对路径，要么是相对路径。绝对路径由一个 <code>/</code> 字符打头。</p><p>相对路径由 <code>.</code> 或者 <code>..</code> 开始。在一个路径中，一个 <code>.</code> 意味着当前目录，<code>..</code> 意味着当前目录的上级目录。比如，<code>ls ../Documents</code> 意味着在此寻找当前目录的上级名为 <code>Documents</code> 的目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pwd</span></span>
<span class="line"><span>/home/student</span></span>
<span class="line"><span>$ ls</span></span>
<span class="line"><span>Desktop Documents Downloads Music Pictures README.txt Videos</span></span>
<span class="line"><span>$ cd Downloads</span></span>
<span class="line"><span>$ pwd</span></span>
<span class="line"><span>/home/student/Downloads</span></span>
<span class="line"><span>$ ls ../Documents</span></span>
<span class="line"><span>report.txt todo.txt EmailHowTo.pdf</span></span></code></pre></div><p>当您第一次打开命令行窗口时，您当前的工作目录被设置为您的家目录，通常为 <code>/home/&lt;您的登录名&gt;</code>。家目录专用于登录之后存储您的专属文件。</p><p>环境变量 <code>$HOME</code> 会展开为您的家目录，比如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo $HOME</span></span>
<span class="line"><span>/home/student</span></span></code></pre></div><p>下表显示了用于目录导航和管理简单的文本文件的一些命令摘要。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/table-1_0.png?itok=j4Sgv6Vy" alt=""></p><h3 id="搜索" tabindex="-1">搜索 <a class="header-anchor" href="#搜索" aria-label="Permalink to “搜索”">​</a></h3><p>有时我们会遗忘文件的位置，或者忘记了我要寻找的文件名。Linux 命令行有几个命令可以帮助您搜索到文件。</p><p>第一个命令是 <code>find</code>。您可以使用 <code>find</code> 命令通过文件名或其他属性搜索文件和目录。举个例子，当您遗忘了 <code>todo.txt</code> 文件的位置，我们可以执行下面的代码：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find $HOME -name todo.txt</span></span>
<span class="line"><span>/home/student/Documents/todo.txt</span></span></code></pre></div><p><code>find</code> 程序有很多功能和选项。一个简单的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find &lt;要寻找的目录&gt; -name &lt;文件名&gt;</span></span></code></pre></div><p>如果这里有 <code>todo.txt</code> 文件且不止一个，它将向我们列出拥有这个名字的所有文件的所有所在位置。<code>find</code> 命令有很多便于搜索的选项比如类型（文件或是目录等等）、时间、大小和其他一些选项。更多内容您可以同通过 <code>man find</code> 获取关于如何使用 <code>find</code> 命令的帮助。</p><p>您还可以使用 <code>grep</code> 命令搜索文件的特定内容，比如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>grep &quot;01/02/2018&quot; todo.txt</span></span></code></pre></div><p>这将为您展示 <code>todo</code> 文件中 <code>01/02/2018</code> 所在行。</p><h3 id="获取帮助" tabindex="-1">获取帮助 <a class="header-anchor" href="#获取帮助" aria-label="Permalink to “获取帮助”">​</a></h3><p>Linux 有很多命令，这里，我们没有办法一一列举。授人以鱼不如授人以渔，所以下一步我们将向您介绍帮助命令。</p><p><code>apropos</code> 命令可以帮助您查找需要使用的命令。也许您想要查找能够操作目录或是获得文件列表的所有命令，但是您不知道该运行哪个命令。您可以这样尝试：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apropos directory</span></span></code></pre></div><p>要在帮助文档中，得到一个于 <code>directiory</code> 关键字的相关命令列表，您可以这样操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apropos &quot;list open files&quot;</span></span></code></pre></div><p>这将提供一个 <code>lsof</code> 命令给您，帮助您列出打开文件的列表。</p><p>当您明确知道您要使用的命令，但是不确定应该使用什么选项完成预期工作，您可以使用 <code>man</code> 命令，它是 manual 的缩写。您可以这样使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man ls</span></span></code></pre></div><p>您可以在自己的设备上尝试这个命令。它会提供给您关于使用这个命令的完整信息。</p><p>通常，很多命令都能够接受 <code>help</code> 选项（比如说，<code>ls --help</code>），列出命令使用的提示。<code>man</code> 页面的内容通常太繁琐，<code>--help</code> 选项可能更适合快速浏览。</p><h3 id="脚本" tabindex="-1">脚本 <a class="header-anchor" href="#脚本" aria-label="Permalink to “脚本”">​</a></h3><p>Linux 命令行中最贴心的功能之一是能够运行脚本文件，并且能重复运行。Linux 命令可以存储在文本文件中，您可以在文件的开头写入 <code>#!/bin/sh</code>，后面的行是命令。之后，一旦文件被存储为可执行文件，您就可以像执行命令一样运行脚本文件，比如，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>--- contents of get_todays_todos.sh ---</span></span>
<span class="line"><span>#!/bin/sh</span></span>
<span class="line"><span>todays_date=\`date +&quot;%m/%d/%y&quot;\`</span></span>
<span class="line"><span>grep $todays_date $HOME/todos.txt</span></span></code></pre></div><p>脚本可以以一套可重复的步骤自动化执行特定命令。如果需要的话，脚本也可以很复杂，能够使用循环、判断语句等。限于篇幅，这里不细述，但是您可以在网上查询到相关信息。</p><h3 id="windows-命令行用户" tabindex="-1">Windows 命令行用户 <a class="header-anchor" href="#windows-命令行用户" aria-label="Permalink to “Windows 命令行用户”">​</a></h3><p>如果您对 Windows CMD 或者 PowerShell 程序很熟悉，在命令行输入命令应该是轻车熟路的。然而，它们之间有很多差异，如果您没有理解它们之间的差异可能会为之困扰。</p><p>首先，在 Linux 下的 <code>PATH</code> 环境与 Windows 不同。在 Windows 中，当前目录被认为是该搜索路径（<code>PATH</code>）中的第一个文件夹，尽管该目录没有在环境变量中列出。而在 Linux 下，当前目录不会明确的放在搜索路径中。Linux 下设置环境变量会被认为是风险操作。在 Linux 的当前目录执行程序，您需要使用 <code>./</code>（代表当前目录的相对目录表示方式） 前缀。这可能会搞糊涂很多 CMD 用户。比如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>./my_program</span></span></code></pre></div><p>而不是</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>my_program</span></span></code></pre></div><p>另外，在 Windows 环境变量的路径中是以 <code>;</code>（分号） 分割的。在 Linux 中，由 <code>:</code> 分割环境变量。同样，在 Linux 中路径由 <code>/</code> 字符分隔，而在 Windows 目录中路径由 <code>\\</code> 字符分割。因此 Windows 中典型的环境变量会像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PATH=&quot;C:\\Program Files;C:\\Program Files\\Firefox;&quot;</span></span></code></pre></div><p>而在 Linux 中看起来像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PATH=&quot;/usr/bin:/opt/mozilla/firefox&quot;</span></span></code></pre></div><p>还要注意，在 Linux 中环境变量由 <code>$</code> 拓展，而在 Windows 中您需要使用百分号（就是这样： <code>%PATH%</code>）。</p><p>在 Linux 中，通过 <code>-</code> 使用命令选项，而在 Windows 中，使用选项要通过 <code>/</code> 字符。所以，在 Linux 中您应该：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>a_prog -h</span></span></code></pre></div><p>而不是</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>a_prog /h</span></span></code></pre></div><p>在 Linux 下，文件拓展名并没有意义。例如，将 <code>myscript</code> 重命名为 <code>myscript.bat</code> 并不会因此而变得可执行，需要设置文件的执行权限。文件执行权限会在下次的内容中覆盖到。</p><p>在 Linux 中，如果文件或者目录名以 <code>.</code> 字符开头，意味着它们是隐藏文件。比如，如果您申请编辑 <code>.bashrc</code> 文件，您不能在家目录中找到它，但是它可能真的存在，只不过它是隐藏文件。在命令行中，您可以通过 <code>ls</code> 命令的 <code>-a</code> 选项查看隐藏文件，比如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ls -a</span></span></code></pre></div><p>在 Linux 中，普通的命令与 Windows 的命令不尽相同。下面的表格显示了常用命令中 CMD 命令和 Linux 命令行的差异。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/table-2_0.png?itok=NNc8TZFZ" alt=""></p><hr>`,67)),e("p",null,[s[8]||(s[8]=i("via: ",-1)),n(a,{href:"https://www.linux.com/blog/learn/2018/1/migrating-linux-command-line"},{default:t(()=>[...s[7]||(s[7]=[i("https://www.linux.com/blog/learn/2018/1/migrating-linux-command-line",-1)])]),_:1})]),e("p",null,[s[12]||(s[12]=i("作者：",-1)),n(a,{href:"https://www.linux.com/users/johnbonesio"},{default:t(()=>[...s[9]||(s[9]=[i("John Bonesio",-1)])]),_:1}),s[13]||(s[13]=i(" 译者：",-1)),n(a,{href:"https://github.com/CYLeft"},{default:t(()=>[...s[10]||(s[10]=[i("CYLeft",-1)])]),_:1}),s[14]||(s[14]=i(" 校对：",-1)),n(a,{href:"https://github.com/wxy"},{default:t(()=>[...s[11]||(s[11]=[i("wxy",-1)])]),_:1})]),e("p",null,[s[17]||(s[17]=i("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[15]||(s[15]=[i("LCTT",-1)])]),_:1}),s[18]||(s[18]=i(" 原创编译，",-1)),n(a,{href:"https://linux.cn/"},{default:t(()=>[...s[16]||(s[16]=[i("Linux中国",-1)])]),_:1}),s[19]||(s[19]=i(" 荣誉推出",-1))])])}const C=l(c,[["render",r]]);export{y as __pageData,C as default};
